import { workspaceMigration } from "@krizaka/organize";

import { WORKSPACE } from "./decl";

/**
 * Migration 0033 (yomizaka#324): the layer's tables, generated by the package from `WORKSPACE` (the drift test in
 * `workspace.test.ts` holds the SQL whole), then the one move of data.
 *
 * The documents' tags were the first layer's (`tags` + `document_tags`, shared with collections and folders). The workspace owns
 * them now — a document's tags are filtered by `filterSql` and worn with their marker — so each tag a document wears becomes the
 * account's tag of kind « document » (same name, same marker) and the old join table goes: one source of truth, never two. The
 * collections' and folders' tags stay as they were.
 */
export const WORKSPACE_MIGRATION = `${workspaceMigration(WORKSPACE)}
INSERT INTO organize.tag (scope_id, kind, name, marker, origin, created_at)
SELECT DISTINCT t.owner_id, 'document', t.name, t.color, 'user', now()
  FROM tags t
 WHERE EXISTS (SELECT 1 FROM document_tags dt WHERE dt.tag_id = t.id)
ON CONFLICT DO NOTHING;

INSERT INTO organize.document_tag (entity_id, tag_id)
SELECT dt.document_id, nt.id
  FROM document_tags dt
  JOIN tags t ON t.id = dt.tag_id
  JOIN organize.tag nt ON nt.scope_id = t.owner_id AND nt.kind = 'document' AND lower(nt.name) = lower(t.name)
ON CONFLICT DO NOTHING;

DROP TABLE document_tags;
`;
